-- Migration 007 — flexport_shipments (Production Planner, FLEXPORT sub-tab)
-- From flexport-Grid view.csv (121 shipments x 39 cols). shipment_name = the PO ref, so this
-- links to purchase_orders (Shipment Name == po). Holds Flexport milestone dates (planned/
-- estimated/actual), container/BOL, costs. HOW TO APPLY: tested on sandbox; BEN runs on live.

create table if not exists planner.flexport_shipments (
  flex_id text primary key,
  shipment_name text,
  mode text,
  status_description text,
  incoterm text,
  freight_type text,
  freight_carriers text,
  mbl_number text,
  container_numbers text,
  cleared_customs_date date,
  ams_numbers text,
  planned_transit_time integer,
  actual_transit_time integer,
  total_quoted_amount numeric(14,2),
  origin_planned_departure date,
  origin_estimated_departure date,
  origin_actual_departure date,
  dep_port_planned_departure date,
  dep_port_estimated_departure date,
  dep_port_actual_departure date,
  arr_port_actual_arrival date,
  arr_port_estimated_arrival date,
  arr_port_planned_arrival date,
  dest_planned_arrival date,
  dest_estimated_arrival date,
  dest_actual_arrival date,
  shipments_ref text,
  packing_date date,
  departure_date date,
  landing_date date,
  arrival_date date,
  estimated_shipment_cost numeric(14,2),
  shipments_2 text,
  last_modified_time text,
  total_invoiced_amount numeric(14,2),
  customs_duty_cost numeric(14,2),
  total_freight_cost numeric(14,2),
  vat_costs numeric(14,2),
  quote_requested_date date
);

comment on table planner.flexport_shipments is 'Flexport shipment data (FLEXPORT tab); shipment_name links to purchase_orders.po.';

